using System;
using System.IO;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

namespace Ashiria.Engine.Tests
{
    /// <summary>
    /// The C# engine must reproduce the Python reference (training/) on the golden vectors in
    /// spec/golden/engine_v1.json, generated by `ashiria golden` from synthetic hands.
    /// </summary>
    public class EngineParityTests
    {
        JObject golden;

        [OneTimeSetUp]
        public void Load()
        {
            var info = UnityEditor.PackageManager.PackageInfo.FindForAssembly(typeof(EngineParityTests).Assembly);
            string root = info != null ? info.resolvedPath : Directory.GetCurrentDirectory();
            string file = Path.GetFullPath(Path.Combine(root, "..", "..", "..", "spec", "golden", "engine_v1.json"));
            Assert.That(File.Exists(file), $"Golden vectors not found at {file}. Run `ashiria golden` in training/.");
            golden = JObject.Parse(File.ReadAllText(file));
            Assert.That((int)golden["spec_version"], Is.EqualTo(Features.SpecVersion));
        }

        static Segment ToSegment(JToken s)
        {
            var hand = (JArray)s["hand_rel"];
            var wrist = (JArray)s["wrist_pos"];
            var present = (JArray)s["present"];
            int n = present.Count;
            var seg = Segment.Empty(n, (float)s["fps"]);
            for (int t = 0; t < n; t++)
            {
                for (int slot = 0; slot < 2; slot++)
                {
                    for (int j = 0; j < Joints.Count; j++)
                    {
                        var p = hand[t][slot][j];
                        seg.HandRel[t, slot, j] = new Vec3((float)p[0], (float)p[1], (float)p[2]);
                    }
                    var w = wrist[t][slot];
                    seg.WristPos[t, slot] = new Vec3((float)w[0], (float)w[1], (float)w[2]);
                    seg.Present[t, slot] = (float)present[t][slot];
                }
            }
            return seg;
        }

        Segment Run(JToken c, out float[,] features)
        {
            var seg = ToSegment(c["segment"]);
            if ((bool)c["mirror"]) seg = Canonical.Mirror(seg);
            seg = Canonical.GapFill(seg, (int)golden["gap_fill_frames"]);
            seg = Canonical.Trim(seg, (float)golden["rest_height"], (int)golden["trim_margin_frames"]);
            Assert.That(seg, Is.Not.Null);
            Assert.That(seg.Length, Is.EqualTo((int)c["trimmed_length"]), $"{c["name"]}: trimmed length");
            var res = Canonical.Resample(seg, (int)golden["seq_len"]);
            features = Features.Sequence(res);
            return res;
        }

        static void AssertClose(JArray expected, float[,] actual, double tol, string what)
        {
            Assert.That(actual.GetLength(0), Is.EqualTo(expected.Count), $"{what}: rows");
            double worst = 0;
            for (int t = 0; t < expected.Count; t++)
            {
                var row = (JArray)expected[t];
                Assert.That(actual.GetLength(1), Is.EqualTo(row.Count), $"{what}: columns");
                for (int k = 0; k < row.Count; k++)
                    worst = Math.Max(worst, Math.Abs((double)row[k] - actual[t, k]));
            }
            Assert.That(worst, Is.LessThanOrEqualTo(tol), $"{what}: max difference {worst:E2}");
        }

        [Test]
        public void ResampledTimingAndPresenceMatch()
        {
            foreach (var c in (JArray)golden["cases"])
            {
                var res = Run(c, out _);
                Assert.That(res.Fps, Is.EqualTo((float)c["resampled_fps"]).Within(1e-3f), $"{c["name"]}: fps");
                var present = (JArray)c["resampled_present"];
                for (int t = 0; t < present.Count; t++)
                    for (int slot = 0; slot < 2; slot++)
                        Assert.That(res.Present[t, slot], Is.EqualTo((float)present[t][slot]), $"{c["name"]}: present[{t},{slot}]");
            }
        }

        [Test]
        public void FeaturesAndDescriptorsMatchPython()
        {
            double tol = (double)golden["tolerance"]["features"];
            foreach (var c in (JArray)golden["cases"])
            {
                Run(c, out var features);
                AssertClose((JArray)c["features"], features, tol, $"{c["name"]} features");
                AssertClose((JArray)c["descriptor"], Matching.Descriptor(features), tol, $"{c["name"]} descriptor");
            }
        }

        [Test]
        public void DtwAndFingerErrorsMatchPython()
        {
            var cases = (JArray)golden["cases"];
            var descriptors = new float[cases.Count][,];
            var flexion = new float[cases.Count][];
            for (int i = 0; i < cases.Count; i++)
            {
                var res = Run(cases[i], out var features);
                descriptors[i] = Matching.Descriptor(features);
                int key = (int)cases[i]["key_frame"];
                var hand = new Vec3[Joints.Count];
                for (int j = 0; j < Joints.Count; j++) hand[j] = res.HandRel[key, Joints.Dominant, j];
                flexion[i] = new float[15];
                Features.Flexion(hand, flexion[i]);
            }
            foreach (var pair in (JArray)golden["dtw"])
            {
                float d = Matching.Dtw(descriptors[(int)pair["a"]], descriptors[(int)pair["b"]]);
                Assert.That(d, Is.EqualTo((float)pair["distance"]).Within((float)golden["tolerance"]["dtw"]));
            }
            foreach (var e in (JArray)golden["finger_errors"])
            {
                var errors = Matching.FingerErrors(flexion[(int)e["attempt"]], flexion[(int)e["reference"]]);
                var expected = (JArray)e["errors"];
                for (int f = 0; f < 5; f++)
                    Assert.That(errors[f], Is.EqualTo((float)expected[f]).Within((float)golden["tolerance"]["finger_errors"]));
            }
        }
    }
}
